printf("Cantidad de equipos: ");
scanf("%d", &nEquipos);
int totalPuntosGeneral = 0;
int contEquipo = 1;

while (contEquipo <= nEquipos) {
    printf("\n=== Equipo #%d ===\n", contEquipo);
    printf("Cantidad de partidos jugados: ");
    scanf("%d", &nPartidos);

    int puntosEquipo = 0;
    int contPartido = 1;

    while (contPartido <= nPartidos) {
        char resultado;
        printf("  Partido #%d (G/E/P): ", contPartido);
        scanf(" %c", &resultado);

        if (resultado == 'G' || resultado == 'g') {
            puntosEquipo = puntosEquipo + 3;
        } else if (resultado == 'E' || resultado == 'e') {
            puntosEquipo = puntosEquipo + 1;
        }
        contPartido = contPartido + 1;
    }

    printf("Puntos del equipo #%d: %d\n", contEquipo, puntosEquipo);
    totalPuntosGeneral = totalPuntosGeneral + puntosEquipo;
    contEquipo = contEquipo + 1;
}
printf("Total de puntos en el torneo: %d\n", totalPuntosGeneral);
```

